const PACK_DIMS = [0.32, 0.091, 0.086];
const PACK_L = PACK_DIMS[0] * PACK_DIMS[1] * PACK_DIMS[2] * 1000;
// Per-run handling (round 4, audit3 A3-LF-05: no constants). Human actions are simulated as a predetermined-motion-time
// sequence (MODAPTS, 1 MOD = 0.129 s; ISO-standard PMTS used in ergonomics) with a glove factor on every hand element
// (ASSUMED 1.3: thick ski gloves; sensitivity 2.0), a ski-boot factor on bending (1.2), seeded ±15 % element scatter and
// seeded retries (gloved grasp miss 8 %, holster snap miss 15 %). Design that makes it short: the wings fold themselves
// (servo) when the rider stops beside it; the holster has a magnetic funnel mouth (snap-in, no zip/flap, no orientation).
//   set-down : reach to holster M3, grasp G3, pull out M4, bend B(½·17), place on snow P2   (rider then rises B(½·17))
//   stow     : bend B(½·17), reach M3, grasp G3, rise B(½·17), move to hip M4, snap P2
// Retrieval moves are simulated kinematics (glide downhill ≤4 m/s, side-step 0.4 m/s, poling across 1.2 m/s).
const MOD = 0.129, GLIDE_V = 4, SIDESTEP_V = 0.4, TRAVERSE_V = 1.2;
export function handling(seed = 1, { glove = 1.3, boot = 1.2, scatter = 0.15, pMissGrasp = 0.08, pMissSnap = 0.15, stowConst = null } = {}) {
  let st = (seed * 2246822519 + 12345) >>> 0;
  const rnd = () => { st = (st + 0x6D2B79F5) >>> 0; let x = st; x = Math.imul(x ^ (x >>> 15), x | 1); x ^= x + Math.imul(x ^ (x >>> 7), x | 61); return ((x ^ (x >>> 14)) >>> 0) / 4294967296; };
  const g = () => { const u = Math.max(1e-9, rnd()), v = rnd(); return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v); };
  const el = (mods, k) => mods * k * MOD * Math.max(0.6, 1 + scatter * g());
  const hand = (m) => el(m, glove), bend = () => el(8.5, boot);
  let setDown = hand(3) + hand(3) + hand(4) + bend() + hand(2);
  if (rnd() < pMissGrasp) setDown += hand(3) + hand(2);
  const rise = bend();
  let stow = bend() + hand(3) + hand(3) + bend() + hand(4) + hand(2);
  if (rnd() < pMissGrasp) stow += hand(3) + hand(2);
  if (rnd() < pMissSnap) stow += hand(2) + hand(2);
  if (stowConst != null) stow = stowConst;
  return { setDown: +setDown.toFixed(2), rise: +rise.toFixed(2), stow: +stow.toFixed(2) };
}
export const PER_RUN = { MOD, GLIDE_V, SIDESTEP_V, TRAVERSE_V, glove: 1.3, boot: 1.2 };
const moveTime = (d, v = GLIDE_V, a = 1.5, b = 2.0) => { if (d <= 0) return 0; const dAcc = (v * v) / (2 * a) + (v * v) / (2 * b); return d >= dAcc ? v / a + v / b + (d - dAcc) / v : Math.sqrt((2 * d) / (a * (1 + a / b))) * (1 + a / b); };

