// rider glides from its stop to beside the perched glider: straight kinematic segment at ≤ v, stop 1.1 m to the side
function retrieveTrack(sk, tStart, target, v = 3.5) {
  const c = sk.col, dt = sk.sampleDt;
  const i0 = Math.max(1, Math.round(tStart / dt));
  let x = c.x[i0 - 1], y = c.y[i0 - 1], sp = 0, hd = Math.atan2(target[1] - y, target[0] - x);
  for (let i = i0; i < sk.n; i++) {
    const dx = target[0] - x, dy = target[1] - y, d = Math.hypot(dx, dy);
    const want = d < 0.15 ? 0 : Math.min(v, Math.sqrt(2 * 1.5 * d));
    sp += Math.max(-2, Math.min(1.2, (want - sp) / dt)) * dt;
    if (d < 0.15) sp = 0;
    const hT = Math.atan2(dy, dx); if (d > 0.5) hd += (hT - hd) * Math.min(1, dt / 0.5);
    x += sp * Math.cos(hd) * dt; y += sp * Math.sin(hd) * dt;
    c.x[i] = x; c.y[i] = y; c.z[i] = -x * sk.tanS; c.psi[i] = hd; c.vx[i] = sp * Math.cos(hd); c.vy[i] = sp * Math.sin(hd); c.hx[i] = Math.cos(hd); c.hy[i] = Math.sin(hd);
    c.v[i] = sp; c.lat[i] = 0; c.lon[i] = 0; c.lean[i] = 0; c.crouch[i] = sp < 0.3 ? 0.12 : 0.25; c.plantL[i] = c.plantR[i] = 0; c.fallen[i] = 0;
  }
  return sk;
}

function buildDemo(params) {
  const mk = () => simulateSkier({ start: 'push', duration: DEMO_T - DEMO_TGO + 1, seed: 2, vTarget: DEMO_V, turnPeriod: 3.2, stopAt: DEMO_STOP });
  const wind = { mean: [0, 1.5, 0], intensity: 0.18, Lu: 30, seed: 4 };
  const sk0 = mk();
  const iS = sk0.n - 1;
  const lift = { pos: [sk0.col.x[iS] + 1.5, sk0.col.y[iS] - 1], rEnd: 70, ahead: 5, lat: 4 };
  const plan = { start: 'setdown', launchAt: 2.5, lift };
  // pass 1: where does it land at the lift?
  const c1 = runCore({ ...PDEF, ...params }, { duration: DEMO_T, skier: sk0, tGo: DEMO_TGO, seed: 5, wind, plan });
  const iL = c1.n - 1, gpos = [c1.O.x[iL], c1.O.y[iL]];
  const sk = mk();
  const tGlide = DEMO_STOP + 5; // skier time when the rider starts gliding up to it
  const side = Math.sign(sk.col.y[Math.round(tGlide / sk.sampleDt)] - gpos[1]) || 1;
  retrieveTrack(sk, tGlide, [gpos[0] - 0.4, gpos[1] + side * 1.1]);
  const prep = { sk, input: { duration: DEMO_T, skier: sk, tGo: DEMO_TGO, seed: 5, wind, plan } };
  let tFold = 99;
  prep.anim = (t, skier, dev, s) => {
    const b = bodyPoints(s), h = s.heading, l = b.left;
    if (t < 2.5) {
      // draw (0.6–1.3 s), bend and set it down on the snow 1.5 m right of the skis (1.3–2.5 s)
      const holster = [b.pelvis[0] - h[0] * 0.08 - l[0] * 0.24, b.pelvis[1] - h[1] * 0.08 - l[1] * 0.24, b.pelvis[2] - 0.05];
      const snow = [s.pos[0] + h[0] * 0.5 - l[0] * 1.5, s.pos[1] + h[1] * 0.5 - l[1] * 1.5, s.pos[2] + 0.06];
      let hand = null, reach = 0, carry = 0;
      if (t > 0.6 && t < 1.3) { hand = holster; reach = smooth((t - 0.6) / 0.5); carry = t > 1.0 ? 1 : 0; }
      else if (t >= 1.3) { const u = smooth((t - 1.3) / 1.0); hand = holster.map((v, k) => v + (snow[k] - v) * u); reach = 1; carry = 1; skier.crouch = Math.max(s.crouch ?? 0.12, 0.7 * u); }
      if (hand) { skier.handR = hand; skier.reachR = reach; }
      if (carry) { dev.inHand = hand; dev.stowed = false; dev.wing = smooth((t - 1.8) / 0.6); dev.dir = [h[0], h[1], 0]; }
    } else if (t < 3.3) { skier.crouch = Math.max(s.crouch ?? 0.12, 0.7 * (1 - smooth((t - 2.5) / 0.8))); }
    // pick-up: reach down to the folded glider (fold + 0.5 s), lift it to the chest, then into the holster
    if (t > tFold + 0.5) {
      const g = dev.pos;
      const grab = [g[0], g[1], g[2] + 0.05];
      const chest = [b.chest[0] + h[0] * 0.3 - l[0] * 0.25, b.chest[1] + h[1] * 0.3 - l[1] * 0.25, b.chest[2]];
      const holster = [b.pelvis[0] - h[0] * 0.08 - l[0] * 0.24, b.pelvis[1] - h[1] * 0.08 - l[1] * 0.24, b.pelvis[2] + 0.1];
      const u1 = smooth((t - tFold - 0.5) / 1.5), u2 = smooth((t - tFold - 2.5) / 1.5), u3 = smooth((t - tFold - 4.5) / 2.5);
      const rest = [b.pelvis[0] - l[0] * 0.3, b.pelvis[1] - l[1] * 0.3, b.pelvis[2]];
      let hand;
      if (u2 <= 0) hand = rest.map((v, k) => v + (grab[k] - v) * u1);
      else if (u3 <= 0) hand = grab.map((v, k) => v + (chest[k] - v) * u2);
      else hand = chest.map((v, k) => v + (holster[k] - v) * u3);
      skier.handR = hand; skier.reachR = 1;
      skier.crouch = Math.max(s.crouch ?? 0.12, 0.75 * u1 * (1 - u2));
      if (u2 > 0) { dev.inHand = hand; dev.wing = 0; dev.dir = [h[0], h[1], 0]; dev.pickup = false; dev.stowT = u3; }
    }
  };
  const sc = { id: 'demo', dur: DEMO_T, skier: {} };
  const R = buildResult(params, sc, prep, { demo: true });
  const pk = R.core.events.find((e) => e.type === 'pickup');
  if (pk) tFold = pk.t;
  R.scenarioId = 'demo';
  return R;
}

